(function(root){'use strict';
function quote(c,method,schedule,model,packages){let total,items,term=c.term||'cycle';if(c.route==='owned'){const p=packages.find(p=>p.id===c.packageId);if(!p)throw Error('Choose a framework.');total=p.price*100;items=[p.name+' — '+p.scope];}else if(c.route==='managed'){if(!Array.isArray(c.departments)||!c.departments.length||new Set(c.departments).size!==c.departments.length||c.departments.some(id=>!model.departments.some(d=>d.id===id)))throw Error('Select at least one service.');const r=model.calculate(c.departments,c.level);total=r.total*100;items=r.selected.map((d,i)=>d.name+' — '+r.allowances[i]);if(term==='annual')total=total*13*.8;else if(term!=='cycle')throw Error('Choose a valid plan.');}else throw Error('Choose an office route.');if(!['usdt','ac'].includes(method)||!['full','installments'].includes(schedule))throw Error('Choose payment options.');const discount=method==='ac'?Math.round(total/10):0;return {subtotal:total,discount,total:total-discount,due:schedule==='installments'?(total-discount)/4:total-discount,items};}
function acTokens(cents){if(!Number.isSafeInteger(cents)||cents<0)throw Error('Invalid service amount');const micro=(BigInt(cents)*50000000000n+2n)/3n;return (micro/1000000n).toString()+'.'+(micro%1000000n).toString().padStart(6,'0')}
root.CheckoutModel={quote,acTokens,acRateUsd:'0.0000006',acRateUntil:'2027-04-29'};if(typeof module!=='undefined')module.exports=root.CheckoutModel;
})(typeof window==='undefined'?globalThis:window);
